import java.util.*;

class Solution {
    public int minSlots(char[] tasks, int n) {
        int[] cnt = new int[26];
        int maxCount = 0;
        for (char c : tasks) maxCount = Math.max(maxCount, ++cnt[c - 'A']);
        int top = 0;                                    // letters tied for the max
        for (int c : cnt) if (c == maxCount) top++;
        int frame = (maxCount - 1) * (n + 1) + top;    // layout forced by the busiest letter
        return Math.max(frame, tasks.length);
    }
}

