class Solution:
    def minSlots(self, tasks: List[str], n: int) -> int:
        h = [-c for c in Counter(tasks).values()]
        heapify(h)
        wait = deque()
        t = 0
        while h or wait:
            t += 1
            if h:
                c = heappop(h) + 1
                if c: wait.append((c, t + n))
            else:
                t = wait[0][1]
            if wait and wait[0][1] == t: heappush(h, wait.popleft()[0])
        return t

