function minSlots(tasks, n) {
  const c = {}; for (const t of tasks) c[t] = (c[t] || 0) + 1;
  const v = Object.values(c), mx = Math.max(...v), top = v.filter(x => x === mx).length;
  return Math.max(tasks.length, (mx - 1) * (n + 1) + top);
}
